import android.Manifest;import android.app.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.speech.*;import android.speech.tts.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;
public class MainActivity extends Activity implements TextToSpeech.OnInitListener{
static final String AI="https://buddy-free-20s07x.v2.appdeploy.ai/api/chat";static final String PNG="";final int BG=Color.rgb(9,7,13),PINK=Color.rgb(255,82,104);LinearLayout chat;TextView status;EditText input;TextToSpeech tts;SpeechRecognizer sr;Handler h=new Handler();boolean speaking;
GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}TextView t(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);return v;}Button b(String s){Button x=new Button(this);x.setText(s);x.setTextColor(Color.WHITE);x.setAllCaps(false);x.setTextSize(12);x.setBackground(bg(Color.rgb(39,29,47),30));return x;}
public void onCreate(Bundle x){super.onCreate(x);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);tts=new TextToSpeech(this,this);ui();}
void ui(){ScrollView sv=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(15,12,15,12);r.setBackgroundColor(BG);sv.addView(r);setContentView(sv);TextView title=t("Little Red's Big Studio",21);title.setTypeface(null,1);r.addView(title,new LinearLayout.LayoutParams(-1,44));TextView sub=t("BUDDY  •  YOUR CREATIVE STUDIO COMPANION",9);sub.setTextColor(Color.rgb(255,143,158));r.addView(sub,new LinearLayout.LayoutParams(-1,24));
FrameLayout stage=new FrameLayout(this);stage.setBackground(bg(Color.rgb(17,12,21),38));r.addView(stage,new LinearLayout.LayoutParams(-1,0,1));ImageView im=new ImageView(this);byte[] raw=Base64.getDecoder().decode(PNG);im.setImageBitmap(BitmapFactory.decodeByteArray(raw,0,raw.length));im.setScaleType(ImageView.ScaleType.FIT_CENTER);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(-1,-1);ip.setMargins(15,10,15,8);stage.addView(im,ip);status=t("Buddy is ready.",11);status.setGravity(17);status.setBackground(bg(Color.argb(225,28,21,34),40));FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(-2,40,Gravity.TOP|Gravity.CENTER_HORIZONTAL);sp.setMargins(0,12,0,0);stage.addView(status,sp);TextView d=t("♫     ♥     ✦     🎧     ✦",12);d.setTextColor(PINK);d.setGravity(17);stage.addView(d,new FrameLayout.LayoutParams(-1,40,Gravity.BOTTOM));
chat=new LinearLayout(this);chat.setOrientation(LinearLayout.VERTICAL);r.addView(chat,new LinearLayout.LayoutParams(-1,225));LinearLayout bar=new LinearLayout(this);bar.setGravity(16);bar.setPadding(7,5,5,5);bar.setBackground(bg(Color.rgb(27,21,32),34));r.addView(bar,new LinearLayout.LayoutParams(-1,58));input=new EditText(this);input.setSingleLine(true);input.setHint("Talk to Buddy…");input.setHintTextColor(Color.rgb(148,138,155));input.setTextColor(Color.WHITE);input.setBackgroundColor(Color.TRANSPARENT);bar.addView(input,new LinearLayout.LayoutParams(0,-1,1));Button mic=b("🎙"),send=b("➤");bar.addView(mic,new LinearLayout.LayoutParams(48,48));bar.addView(send,new LinearLayout.LayoutParams(48,48));mic.setOnClickListener(v->listen());send.setOnClickListener(v->send(input.getText().toString()));TextView f=t("Camera   •   Screen   •   Voice   •   Memory   •   Free-first",9);f.setGravity(17);f.setTextColor(Color.rgb(140,129,149));r.addView(f,new LinearLayout.LayoutParams(-1,32));add("Hi. I'm Buddy. I'm ready.",false);}
void add(String s,boolean u){TextView v=t(s,13);v.setPadding(14,10,14,10);v.setBackground(bg(u?Color.rgb(57,29,41):Color.rgb(28,22,33),22));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.gravity=u?Gravity.RIGHT:Gravity.LEFT;p.setMargins(u?50:0,4,u?0:50,4);chat.addView(v,p);}
void status(String s){runOnUiThread(()->status.setText(s));}
void send(String q){q=q.trim();if(q.isEmpty()||speaking)return;input.setText("");add(q,true);status("Buddy is thinking…");String m=q;new Thread(()->{try{JSONObject j=new JSONObject();j.put("message",m);j.put("history",new JSONArray());j.put("memory","");HttpURLConnection c=(HttpURLConnection)new URL(AI).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(10000);c.setReadTimeout(30000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(j.toString().getBytes("UTF-8"));}if(c.getResponseCode()/100!=2)throw new IOException();BufferedReader q1=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder z=new StringBuilder();String l;while((l=q1.readLine())!=null)z.append(l);String reply=new JSONObject(z.toString()).optString("text","").trim();if(reply.isEmpty())throw new IOException();runOnUiThread(()->{add(reply,false);speak(reply);});}catch(Exception e){status("Buddy could not reach the free AI service. Try again.");}}).start();}
void listen(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},42);return;}if(sr!=null){try{sr.stopListening();sr.destroy();}catch(Exception e){}sr=null;status("Buddy is ready.");return;}if(!SpeechRecognizer.isRecognitionAvailable(this)){status("Phone speech recognition is unavailable.");return;}sr=SpeechRecognizer.createSpeechRecognizer(this);sr.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){status("Listening…");}public void onBeginningOfSpeech(){}public void onRmsChanged(float x){}public void onBufferReceived(byte[] x){}public void onEndOfSpeech(){}public void onError(int e){clean();status("Speech recognition stopped.");}public void onResults(Bundle b){ArrayList<String>x=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);clean();if(x!=null&&!x.isEmpty())send(x.get(0));}public void onPartialResults(Bundle b){}public void onEvent(int a,Bundle b){}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"en-US");sr.startListening(i);}
void clean(){if(sr!=null){try{sr.destroy();}catch(Exception e){}sr=null;}}public void onInit(int r){if(r==TextToSpeech.SUCCESS)tts.setLanguage(Locale.US);}void speak(String s){speaking=true;status("Buddy is speaking…");tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,"buddy");h.postDelayed(()->{speaking=false;status("Buddy is ready.");},Math.max(1200,Math.min(10000,s.length()*45L)));}protected void onDestroy(){clean();if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}}
